import {createEnergyResults} from './energy-results.mjs';
import {createEnergySpacing} from './energy-spacing.mjs';
import {createEnergyExam,finishEnergyExam,examCorrect} from './energy-exam-model.mjs';
import {faultCatalog} from './energy-faults.mjs';
let storage;try{storage=localStorage;}catch{}const results=createEnergyResults(storage),spacing=createEnergySpacing(storage),key='mecanica.energy-exam.v1';let exam=null,warning='',selected=0,ready=false,reviewRepaired=false;
try{const s=JSON.parse(storage.getItem(key)||'null');if(s&&['active','finished'].includes(s.status)&&Array.isArray(s.cases)&&s.cases.length===3&&s.cases.every(c=>faultCatalog[c.lab]&&Array.isArray(c.faults)&&c.faults.length&&c.faults.every(f=>faultCatalog[c.lab].some(x=>x.id===f)))&&Array.isArray(s.answers)&&s.answers.length<=3&&s.answers.every(Array.isArray))exam=s;}catch{warning='No se pudo recuperar el intento anterior.';}
const panel=document.querySelector('#exam'),frame=document.querySelector('#lab'),names={transformload:'Transformador',opamp:'Operacional',relief:'Hidráulica'};
function persist(){try{storage.setItem(key,JSON.stringify(exam));}catch{warning='El examen solo se conserva en esta sesión.';}}
function send(){if(ready){const c=exam.cases[selected];frame.contentWindow.postMessage({type:'energy-exam-case',faults:c.faults,level:c.level,repaired:reviewRepaired},location.origin);}}
function view(i,repaired=false){selected=i;reviewRepaired=repaired;const url='index.html?id='+exam.cases[i].lab+'&exam=1';frame.hidden=false;if(frame.getAttribute('src')===url){send();}else{ready=false;frame.src=url;}render();}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;if(e.data?.type==='energy-exam-ready'){ready=true;send();render();}if(e.data?.type==='concept-height'&&Number.isFinite(e.data.height))frame.style.height=Math.min(14000,Math.max(700,e.data.height))+'px';});
function render(){panel.replaceChildren();const el=(tag,text,parent=panel)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const button=(text,fn)=>{const b=el('button',text);b.onclick=fn;return b;};if(warning||results.warning())el('p',warning||results.warning());
if(!exam){button('Comenzar examen',()=>{exam=createEnergyExam(results.all());persist();view(0);});return;}
if(exam.status==='active'){const i=exam.answers.length;if(i>=3){finish();return;}el('h2','Caso '+(i+1)+' / 3 · '+names[exam.cases[i].lab]);el('p','A es la referencia normal; B tiene una o varias averías. Observa varios instantes antes de responder.');const form=el('form','');for(const f of faultCatalog[exam.cases[i].lab]){const label=el('label','',form),input=el('input','',label);input.type='checkbox';input.value=f.id;label.append(document.createTextNode(f.label));}const submit=el('button',ready?'Guardar respuesta y continuar':'Cargando bancos…',form);submit.disabled=!ready;form.onsubmit=e=>{e.preventDefault();const answer=[...form.querySelectorAll('input:checked')].map(x=>x.value);if(!answer.length){el('p','Selecciona al menos una causa.');return;}exam.answers.push(answer);persist();if(exam.answers.length===3)finish();else view(exam.answers.length);};return;}
const good=exam.cases.filter((c,i)=>examCorrect(c,exam.answers[i])).length;el('h2','Resultado: '+Math.round(good/3*100)+'/100 · '+good+'/3 casos');el('p','Cada caso vale 100 si identificaste exactamente todas las causas, o 0 si omitiste o añadiste alguna. Los errores y niveles ajustan tus repasos; solo los casos correctos cuentan para la meta diaria.');
exam.cases.forEach((c,i)=>{const card=el('article','');card.className='exam-result';const label=f=>faultCatalog[c.lab].find(x=>x.id===f)?.label||f;el('h3',names[c.lab]+' · '+(examCorrect(c,exam.answers[i])?'Correcto':'Para repasar'),card);el('p','Elegiste: '+exam.answers[i].map(label).join(', ')+'. Causas reales: '+c.faults.map(label).join(', ')+'.',card);const missing=c.faults.filter(f=>!exam.answers[i].includes(f)),extra=exam.answers[i].filter(f=>!c.faults.includes(f));if(missing.length)el('p','Te faltó identificar: '+missing.map(label).join(', ')+'.',card);if(extra.length)el('p','Señalaste sin evidencia en este caso: '+extra.map(label).join(', ')+'.',card);el('p',c.faults.map(f=>faultCatalog[c.lab].find(x=>x.id===f).explain).join(' '),card);for(const [text,repaired]of [['Comparar con avería',false],['Ver ambos reparados',true]]){const b=el('button',text,card);b.onclick=()=>view(i,repaired);}const a=el('a','Repasar este laboratorio ↗',card);a.href='index.html?id='+c.lab+'&review='+c.faults[0];});button('Nuevo examen',()=>{exam=createEnergyExam(results.all());persist();view(0);});}
function finish(){finishEnergyExam(exam,results);spacing.sync(results.all());persist();view(0);}
if(exam?.status==='finished'){finishEnergyExam(exam,results);spacing.sync(results.all());view(0);}else if(exam?.answers.length===3)finish();else if(exam)view(exam.answers.length);else render();
window.energyExamDebug=()=>({exam,ready,selected,reviewRepaired});
